/* =========================================================
   RAMIS PREMIUM PAGE HERO
   Primary  : #006660
   Accent   : #FFCE3A
   Container: 252fe49
========================================================= */

selector {
    --primary: #006660;
    --primary-dark: #003f3c;
    --accent: #FFCE3A;

    position: relative;
    overflow: hidden;

    min-height: 360px;

    display: flex;
    align-items: center;

    background:
        radial-gradient(
            circle at 8% 15%,
            rgba(0, 102, 96, 0.75),
            transparent 34%
        ),
        radial-gradient(
            circle at 92% 85%,
            rgba(255, 206, 58, 0.10),
            transparent 28%
        ),
        radial-gradient(
            circle at 50% 100%,
            rgba(0, 102, 96, 0.45),
            transparent 42%
        ),
        linear-gradient(
            135deg,
            #003f3c 0%,
            #005550 48%,
            #002f2d 100%
        ) !important;

    border-radius: 0 0 32px 32px;

    box-shadow:
        0 18px 55px rgba(0, 63, 60, 0.16);

    color: #ffffff;

    isolation: isolate;
}


/* =========================================================
   نور بزرگ پس زمینه
========================================================= */

selector::before {
    content: "";

    position: absolute;

    width: 520px;
    height: 520px;

    top: -330px;
    right: -100px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,206,58,0.12) 0%,
            rgba(255,206,58,0.035) 42%,
            transparent 70%
        );

    filter: blur(5px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   افکت نور دوم
========================================================= */

selector::after {
    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    left: -180px;
    bottom: -220px;

    border-radius: 50%;

    background: rgba(0, 180, 165, 0.16);

    filter: blur(35px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   کانتینر متن
========================================================= */

selector .elementor-element-79422f1 {

    position: relative;

    z-index: 3;

    padding: 15px 10px;

    max-width: 650px;
}


/* =========================================================
   عنوان اصلی
========================================================= */

selector .elementor-element-fc6fc09 p {

    position: relative;

    display: inline-block;

    margin: 0 0 20px !important;

    color: #ffffff !important;

    font-size: clamp(30px, 4vw, 48px) !important;

    font-weight: 900 !important;

    line-height: 1.35 !important;

    letter-spacing: -1px;

    text-shadow:
        0 8px 30px rgba(0,0,0,0.15);
}


/* خط طلایی کنار عنوان */

selector .elementor-element-fc6fc09 p::after {

    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: var(--accent);

    border-radius: 20px;

    box-shadow:
        0 4px 15px rgba(255,206,58,0.22);
}


/* =========================================================
   متن توضیحات
========================================================= */

selector .elementor-element-ea22667 p {

    color: rgba(255,255,255,0.72) !important;

    font-size: 15px !important;

    line-height: 2.15 !important;

    margin: 0 0 4px !important;

    max-width: 570px;
}


/* =========================================================
   کانتینر تصویر
========================================================= */

selector .elementor-element-b8d20f6 {

    position: relative;

    z-index: 2;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 10px;
}


/* =========================================================
   خود تصویر
========================================================= */

selector .elementor-element-0e7fd02 {

    position: relative;

    width: 100%;
    max-width: 470px;

    transform: rotate(2deg);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        filter .5s ease;
}


/* قاب تصویر */

selector .elementor-element-0e7fd02::before {

    content: "";

    position: absolute;

    inset: -12px;

    border-radius: 26px;

    background:
        linear-gradient(
            135deg,
            rgba(255,206,58,0.35),
            rgba(255,255,255,0.05),
            rgba(0,102,96,0.25)
        );

    z-index: -1;

    opacity: .7;

    transition: all .4s ease;
}


/* تصویر */

selector .elementor-element-0e7fd02 img {

    width: 100%;

    display: block;

    aspect-ratio: 3 / 2;

    object-fit: cover;

    border-radius: 22px;

    border:
        1px solid rgba(255,255,255,0.14);

    box-shadow:
        0 25px 55px rgba(0,0,0,0.24),
        0 0 0 1px rgba(255,255,255,0.04);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        box-shadow .5s ease,
        filter .5s ease;
}


/* =========================================================
   Hover تصویر
========================================================= */

selector .elementor-element-b8d20f6:hover
.elementor-element-0e7fd02 {

    transform:
        rotate(0deg)
        translateY(-7px);
}


selector .elementor-element-b8d20f6:hover
.elementor-element-0e7fd02::before {

    opacity: 1;

    inset: -16px;

    background:
        linear-gradient(
            135deg,
            rgba(255,206,58,0.45),
            rgba(255,255,255,0.08),
            rgba(0,102,96,0.30)
        );
}


selector .elementor-element-b8d20f6:hover
.elementor-element-0e7fd02 img {

    transform: scale(1.025);

    box-shadow:
        0 30px 65px rgba(0,0,0,0.30),
        0 0 35px rgba(255,206,58,0.08);
}


/* =========================================================
   دکور نقطه‌ای
========================================================= */

selector .elementor-element-79422f1::before {

    content: "";

    position: absolute;

    width: 7px;
    height: 7px;

    right: -35px;
    top: 35px;

    background: var(--accent);

    border-radius: 50%;

    box-shadow:
        0 0 0 7px rgba(255,206,58,0.07),
        0 0 25px rgba(255,206,58,0.30);

    opacity: .8;
}


/* =========================================================
   خط ظریف پایین سکشن
========================================================= */

selector > .elementor-element-79422f1::after {

    content: "";

    position: absolute;

    bottom: 0;
    right: 8%;

    width: 84%;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,206,58,0.25),
            transparent
        );

    pointer-events: none;
}


/* =========================================================
   Tablet
========================================================= */

@media (max-width: 1024px) {

    selector {

        min-height: 330px;

        border-radius: 0 0 26px 26px;
    }

    selector .elementor-element-0e7fd02 {

        max-width: 400px;
    }

    selector .elementor-element-fc6fc09 p {

        font-size: 38px !important;
    }

}


/* =========================================================
   Mobile
========================================================= */

@media (max-width: 767px) {

    selector {

        min-height: auto;

        padding-top: 50px !important;
        padding-bottom: 45px !important;

        border-radius: 0 0 22px 22px;

        background:
            radial-gradient(
                circle at 100% 0%,
                rgba(255,206,58,0.10),
                transparent 35%
            ),
            linear-gradient(
                145deg,
                #003f3c,
                #005550,
                #002f2d
            ) !important;
    }


    selector .elementor-element-79422f1 {

        text-align: center;

        padding: 0 10px;
    }


    selector .elementor-element-fc6fc09 p {

        font-size: 30px !important;

        letter-spacing: -.5px;

        margin-bottom: 16px !important;
    }


    selector .elementor-element-fc6fc09 p::after {

        margin: 12px auto 0;

        width: 45px;
    }


    selector .elementor-element-ea22667 p {

        font-size: 13.5px !important;

        line-height: 2 !important;

        padding: 0 8px;
    }


    selector .elementor-element-b8d20f6 {

        margin-top: 30px;
    }


    selector .elementor-element-0e7fd02 {

        max-width: 100%;

        transform: rotate(0deg);
    }


    selector .elementor-element-0e7fd02 img {

        border-radius: 18px;

        box-shadow:
            0 20px 40px rgba(0,0,0,0.25);
    }


    selector .elementor-element-b8d20f6:hover
    .elementor-element-0e7fd02 {

        transform: translateY(-4px);
    }


    selector .elementor-element-79422f1::before {

        display: none;
    }

}


/* =========================================================
   کاهش انیمیشن برای کاربران حساس
========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {

        transition: none !important;

        animation: none !important;
    }
}

